import{_ as o,o as t,c as s,a3 as d}from"./chunks/framework._FWOmmqu.js";const h=JSON.parse('{"title":"Tenant API v1 — AI Assistant","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant API v1 — AI Assistant | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/api/tenant-v1-ai"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant API v1 — AI Assistant | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/api/tenant-v1-ai"}]]},"headers":[],"relativePath":"api/tenant-v1-ai.md","filePath":"api/tenant-v1-ai.md","lastUpdated":1789669215000}'),a={name:"api/tenant-v1-ai.md"};function n(i,e,c,r,p,l){return t(),s("div",null,[...e[0]||(e[0]=[d('<h1 id="tenant-api-v1-—-ai-assistant" tabindex="-1">Tenant API v1 — AI Assistant <a class="header-anchor" href="#tenant-api-v1-—-ai-assistant" aria-label="Permalink to &quot;Tenant API v1 — AI Assistant&quot;">​</a></h1><p>Base path: <code>/api/tenant/v1</code></p><p>Middleware: <code>auth:tenant-api</code>, <code>tenant.user</code>, <code>not.suspended</code>, <code>verified</code>, <code>module:ai</code>, plus Spatie permissions noted per route.</p><p>Billing: Platform mode burns wallet credits (HTTP <strong>402</strong> when insufficient). BYOK uses the tenant provider key and does not debit the wallet.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Permission</th><th>Purpose</th></tr></thead><tbody><tr><td><code>ai.use</code></td><td>Conversations, messages, credits summary, Lead Copilot</td></tr><tr><td><code>ai.confirm</code></td><td>Confirm or cancel pending write actions</td></tr><tr><td><code>ai.manage</code></td><td>Update/test workspace AI settings (<code>PUT /settings</code> AI keys, <code>POST /settings/test-ai</code>)</td></tr></tbody></table><h2 id="credits" tabindex="-1">Credits <a class="header-anchor" href="#credits" aria-label="Permalink to &quot;Credits&quot;">​</a></h2><h3 id="get-ai-credits" tabindex="-1">GET <code>/ai/credits</code> <a class="header-anchor" href="#get-ai-credits" aria-label="Permalink to &quot;GET `/ai/credits`&quot;">​</a></h3><p>Requires <code>ai.use</code>. Runs <code>ensurePeriod()</code> then returns dual-balance wallet summary and recent ledger entries.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;included_remaining&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">275</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;prepaid_balance&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;available&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1275</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;period_ym&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-08&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;recent_ledger&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: []</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="conversations" tabindex="-1">Conversations <a class="header-anchor" href="#conversations" aria-label="Permalink to &quot;Conversations&quot;">​</a></h2><h3 id="get-ai-conversations" tabindex="-1">GET <code>/ai/conversations</code> <a class="header-anchor" href="#get-ai-conversations" aria-label="Permalink to &quot;GET `/ai/conversations`&quot;">​</a></h3><p>List current user&#39;s conversations (newest first). Requires <code>ai.use</code>.</p><p>Query: <code>limit</code> (default 20).</p><h3 id="post-ai-conversations" tabindex="-1">POST <code>/ai/conversations</code> <a class="header-anchor" href="#post-ai-conversations" aria-label="Permalink to &quot;POST `/ai/conversations`&quot;">​</a></h3><p>Create a conversation. Body: optional <code>context</code> object (page/module hints).</p><h3 id="get-ai-conversations-conversation" tabindex="-1">GET <code>/ai/conversations/{conversation}</code> <a class="header-anchor" href="#get-ai-conversations-conversation" aria-label="Permalink to &quot;GET `/ai/conversations/{conversation}`&quot;">​</a></h3><p>Fetch conversation with messages. Scoped to the authenticated user; foreign workspace IDs → <strong>404</strong>.</p><h3 id="post-ai-conversations-conversation-messages" tabindex="-1">POST <code>/ai/conversations/{conversation}/messages</code> <a class="header-anchor" href="#post-ai-conversations-conversation-messages" aria-label="Permalink to &quot;POST `/ai/conversations/{conversation}/messages`&quot;">​</a></h3><p>Send a user message and receive structured assistant output.</p><p>Body:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;What should I focus on today?&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;context&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;module&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tasks&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Success payload includes:</p><ul><li><code>structured.answer</code>, <code>structured.insights</code>, <code>structured.suggested_actions</code>, <code>structured.references</code></li><li><code>usage</code> token counts and <code>credits_burned</code> (platform mode)</li><li><code>recent_messages</code> (latest user + assistant turns)</li></ul><p>Errors:</p><table tabindex="0"><thead><tr><th>Code</th><th>When</th></tr></thead><tbody><tr><td><strong>402</strong></td><td>Platform wallet empty or below pre-provider credit ceiling (<code>insufficient_ai_credits</code>)</td></tr><tr><td><strong>429</strong></td><td>AI route rate limit (<code>throttle:ai</code>)</td></tr><tr><td><strong>503</strong></td><td>AI disabled platform-wide or module not entitled</td></tr><tr><td><strong>422</strong></td><td>Validation</td></tr></tbody></table><h2 id="pending-write-actions" tabindex="-1">Pending write actions <a class="header-anchor" href="#pending-write-actions" aria-label="Permalink to &quot;Pending write actions&quot;">​</a></h2><p>Low-risk writes (for example <code>create_task</code>) create a pending row first.</p><h3 id="post-ai-actions-action-confirm" tabindex="-1">POST <code>/ai/actions/{action}/confirm</code> <a class="header-anchor" href="#post-ai-actions-action-confirm" aria-label="Permalink to &quot;POST `/ai/actions/{action}/confirm`&quot;">​</a></h3><p>Requires <code>ai.confirm</code>. Executes the tool (also requires underlying domain permission, e.g. <code>tasks.create</code>).</p><h3 id="post-ai-actions-action-cancel" tabindex="-1">POST <code>/ai/actions/{action}/cancel</code> <a class="header-anchor" href="#post-ai-actions-action-cancel" aria-label="Permalink to &quot;POST `/ai/actions/{action}/cancel`&quot;">​</a></h3><p>Requires <code>ai.confirm</code>. Marks pending action cancelled.</p><h2 id="lead-copilot" tabindex="-1">Lead Copilot <a class="header-anchor" href="#lead-copilot" aria-label="Permalink to &quot;Lead Copilot&quot;">​</a></h2><p>Requires <code>ai.use</code> and <code>view</code> policy on the lead.</p><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Description</th></tr></thead><tbody><tr><td>POST</td><td><code>/ai/leads/{lead}/summarize</code></td><td>One-paragraph overview + themes</td></tr><tr><td>POST</td><td><code>/ai/leads/{lead}/next-action</code></td><td>Recommended next step</td></tr><tr><td>POST</td><td><code>/ai/leads/{lead}/draft-follow-up</code></td><td>Draft message; body <code>channel</code>: <code>general</code> | <code>email</code> | <code>whatsapp</code></td></tr></tbody></table><p>Responses mirror conversation message structured output + <code>usage</code>.</p><h2 id="agent-tools-server-side" tabindex="-1">Agent tools (server-side) <a class="header-anchor" href="#agent-tools-server-side" aria-label="Permalink to &quot;Agent tools (server-side)&quot;">​</a></h2><p>Tools are not direct HTTP endpoints. The registry exposes them to the agent when module + permission gates pass:</p><p><strong>Workspace</strong> (available with <code>ai.use</code>; per-module entitlement + view inside providers): <code>search_workspace</code></p><p><strong>Leads</strong> (<code>leads.view</code> / <code>leads.update</code> / <code>leads.assign</code>): <code>search_leads</code>, <code>get_lead</code>, <code>get_stale_leads</code>, <code>get_recent_lead_activity</code>, <code>update_lead_status</code> (pending confirmation), <code>assign_lead</code> (pending confirmation; <code>assigned_to</code> is user id or null to unassign), <code>add_lead_note</code> (pending confirmation; text only)</p><p><strong>Tasks</strong> (<code>tasks.view</code> / <code>tasks.create</code> / <code>tasks.update</code> / <code>tasks.assign</code> / <code>tasks.complete</code>): <code>search_tasks</code>, <code>get_my_tasks</code>, <code>get_overdue_tasks</code>, <code>get_tasks_due_today</code>, <code>get_task</code>, <code>create_task</code> (pending confirmation), <code>update_task_status</code> (pending confirmation; visible with <code>tasks.update</code> <strong>or</strong> <code>tasks.complete</code>; complete/reopen need <code>tasks.complete</code> at propose+confirm; other statuses need <code>tasks.update</code>), <code>assign_task</code> (pending confirmation), <code>add_task_note</code> (pending confirmation; text only)</p><p><strong>Projects</strong> (<code>projects.view</code> / <code>projects.update</code> / <code>projects.assign</code>): <code>search_projects</code>, <code>get_project</code>, <code>get_overdue_projects</code>, <code>update_project_status</code> (pending confirmation; requires <code>projects.update</code>; same as HTTP <code>POST …/status</code>), <code>assign_project</code> (pending confirmation), <code>add_project_note</code> (pending confirmation; text only)</p><p><strong>Opportunities</strong> (<code>opportunities.view</code> / <code>opportunities.update</code> / <code>opportunities.assign</code>): <code>search_opportunities</code>, <code>get_pipeline_summary</code>, <code>get_opportunity_stages</code>, <code>get_opportunity</code>, <code>update_opportunity_stage</code> (pending confirmation; <code>stage_id</code> integer), <code>assign_opportunity</code> (pending confirmation), <code>add_opportunity_note</code> (pending confirmation; text only)</p><p><strong>Invoices</strong> (<code>invoices.view</code> / <code>invoices.update</code> / <code>invoices.assign</code> / <code>invoices.send</code> / <code>invoices.void</code>): <code>get_overdue_invoices</code>, <code>get_invoice_balance_summary</code>, <code>get_invoice</code>, <code>update_invoice_status</code> (pending confirmation; visible with <code>invoices.update</code> <strong>or</strong> <code>invoices.send</code> <strong>or</strong> <code>invoices.void</code>; Unpaid needs <code>send</code>, Cancelled needs <code>void</code>, other targets need <code>update</code> at propose+confirm — same as HTTP <code>POST …/status</code>), <code>assign_invoice</code> (pending confirmation), <code>add_invoice_note</code> (pending confirmation; text only)</p><p><strong>Estimates</strong> (<code>estimates.view</code> / <code>estimates.update</code> / <code>estimates.assign</code> / <code>estimates.send</code> / <code>estimates.accept</code>): <code>get_estimate</code>, <code>update_estimate_status</code> (pending confirmation; visible with <code>estimates.update</code> <strong>or</strong> <code>send</code> <strong>or</strong> <code>accept</code>; Sent needs <code>send</code>, Accepted needs <code>accept</code>, other targets need <code>update</code> at propose+confirm — same as HTTP <code>POST …/status</code>), <code>assign_estimate</code> (pending confirmation), <code>add_estimate_note</code> (pending confirmation; text only)</p><p><strong>Quotations</strong> (<code>quotations.view</code> / <code>quotations.update</code> / <code>quotations.assign</code> / <code>quotations.send</code> / <code>quotations.accept</code>): <code>get_quotation</code>, <code>update_quotation_status</code> (pending confirmation; visible with <code>quotations.update</code> <strong>or</strong> <code>send</code> <strong>or</strong> <code>accept</code>; Sent needs <code>send</code>, Accepted needs <code>accept</code>, other targets need <code>update</code> at propose+confirm — same as HTTP <code>POST …/status</code>), <code>assign_quotation</code> (pending confirmation; <code>EligibleOpportunityAssignee</code>), <code>add_quotation_note</code> (pending confirmation; text only). Quotation payloads expose <code>title</code> (no <code>number</code> field).</p><p><strong>Payments</strong> (<code>payments.view</code> / <code>payments.update</code> / <code>payments.assign</code> / <code>payments.post</code> / <code>payments.void</code>): <code>get_payment</code>, <code>update_payment_status</code> (pending confirmation; visible with <code>payments.update</code> <strong>or</strong> <code>post</code> <strong>or</strong> <code>void</code>; Posted confirm calls <code>post()</code>, Void confirm calls <code>void()</code>; Draft target rejected), <code>assign_payment</code> (pending confirmation), <code>add_payment_note</code> (pending confirmation; text only)</p><p><strong>Credit Notes</strong> (<code>credit-notes.view</code> / <code>credit-notes.update</code> / <code>credit-notes.assign</code> / <code>credit-notes.issue</code> / <code>credit-notes.apply</code> / <code>credit-notes.void</code> / <code>credit-notes.refund</code>): <code>get_credit_note</code>, <code>update_credit_note_status</code> (pending confirmation; visible with <code>credit-notes.update</code> <strong>or</strong> <code>issue</code> <strong>or</strong> <code>apply</code> <strong>or</strong> <code>void</code> <strong>or</strong> <code>refund</code>; Issued confirm calls <code>issue()</code>, Applied calls <code>apply()</code>, Void calls <code>void()</code>, Refunded calls <code>refund()</code>; Draft target rejected), <code>assign_credit_note</code> (pending confirmation; <code>EligibleCreditNoteAssignee</code>), <code>add_credit_note_note</code> (pending confirmation; text only)</p><p><strong>Purchase Orders</strong> (<code>purchase-orders.view</code> / <code>purchase-orders.update</code> / <code>purchase-orders.assign</code> / <code>purchase-orders.send</code> / <code>purchase-orders.receive</code> / <code>purchase-orders.cancel</code>): <code>get_purchase_order</code>, <code>update_purchase_order_status</code> (pending confirmation; visible with <code>purchase-orders.update</code> <strong>or</strong> <code>send</code> <strong>or</strong> <code>receive</code> <strong>or</strong> <code>cancel</code>; target-dependent auth at propose+confirm — same as HTTP <code>POST …/status</code>), <code>assign_purchase_order</code> (pending confirmation), <code>add_purchase_order_note</code> (pending confirmation; text only)</p><p><strong>Help Desk</strong> (<code>help-desk.view</code> / <code>help-desk.update</code> / <code>help-desk.assign</code>): <code>get_help_desk_open_tickets</code>, <code>get_help_desk_ticket</code>, <code>update_help_desk_ticket_status</code> (pending confirmation; resolve/close also need <code>help-desk.close</code> at confirm), <code>assign_help_desk_ticket</code> (pending confirmation), <code>add_help_desk_ticket_note</code> (pending confirmation; text only)</p><p><strong>Expenses</strong> (<code>expenses.view</code> / <code>expenses.update</code> / <code>expenses.assign</code> / <code>expenses.submit</code> / <code>expenses.approve</code> / <code>expenses.reject</code> / <code>expenses.pay</code> / <code>expenses.cancel</code>): <code>get_expense_pending_approval</code>, <code>get_expense</code>, <code>update_expense_status</code> (pending confirmation; visible with <code>expenses.update</code> <strong>or</strong> <code>submit</code> <strong>or</strong> <code>approve</code> <strong>or</strong> <code>reject</code> <strong>or</strong> <code>pay</code> <strong>or</strong> <code>cancel</code>; target-dependent auth at propose+confirm — same as HTTP <code>POST …/status</code>; Paid uses <code>pay([])</code> so Accounting workspaces need <code>paid_from_account_id</code> already on the expense), <code>assign_expense</code> (pending confirmation), <code>add_expense_note</code> (pending confirmation; text only)</p><p><strong>Leave Management</strong> (<code>leave-management.view</code> / <code>leave-management.approve</code>): <code>get_leave_request</code>, <code>get_pending_leave_requests</code> (status=<code>pending</code>), <code>approve_leave_request</code> (pending confirmation; optional <code>review_notes</code> / <code>deduct_salary</code>; notes required when overriding default salary deduction; mirrors HTTP <code>POST …/approve</code>; non-admins cannot approve their own request), <code>reject_leave_request</code> (pending confirmation; <strong>required</strong> <code>review_notes</code>; mirrors HTTP <code>POST …/reject</code>). No assign or timeline-note tools.</p><p>Tool list/detail rows expose numeric <code>id</code> (SPA paths) and <code>uuid</code> (lookups). Assignee fields use numeric <code>assigned_to</code> (user id) plus <code>assignee_name</code> when present. <code>search_workspace</code> hits also include <code>path</code> for citations; responses may list <code>modules_failed</code> when a provider errors without failing the whole tool. See <a href="/developer-guide/ai-tools">AI tools guide</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/architecture/ai-platform">AI platform architecture</a></li><li><a href="/developer-guide/ai-credits">AI credits</a></li><li><a href="/user-guide/ai-assistant">AI Assistant user guide</a></li></ul>',55)])])}const u=o(a,[["render",n]]);export{h as __pageData,u as default};
